IF	OBJECT_ID('ResetBlance_RecoveryData_18032025') IS NOT NULL
DROP TABLE	ResetBlance_RecoveryData_18032025;

CREATE TABLE ResetBlance_RecoveryData_18032025(
	CustId			INT PRIMARY KEY,
	ResetDate 		DATE NOT NULL,
	CreatedTime		DATETIME NOT NULL,
	InsertTime		DATETIME NOT NULL
);

IF	OBJECT_ID('tempdb..#temp_ExcludedCustomers') IS NOT NULL
DROP TABLE	#temp_ExcludedCustomers;

CREATE TABLE #temp_ExcludedCustomers(
	CustID BIGINT PRIMARY KEY
);

IF	OBJECT_ID('tempdb..#tmpResetBlance') IS NOT NULL
DROP TABLE	#tmpResetBlance;

CREATE TABLE #tmpResetBlance(
	CustId			INT PRIMARY KEY,
	ResetDate 		DATE NOT NULL,
	CreatedTime		DATETIME NOT NULL
);

-- #0. Get Excluded Customers
INSERT INTO  #temp_ExcludedCustomers (CustID) 
SELECT DISTINCT CAST(val AS INT) CustID 
FROM dbo.SPU_StrSplit(@excludedCustIDs, ',')

INSERT INTO #temp_ExcludedCustomers (CustID) 
SELECT DISTINCT CAST(val AS INT) CustID 
FROM dbo.SPU_StrSplit(@excludedPAVVIP, ',')
WHERE NOT EXISTS (SELECT 1 FROM #temp_ExcludedCustomers AS e WHERE e.CustID = val);

-- #1. Get latest ResetBalance
INSERT INTO #tmpResetBlance (CustId, ResetDate, CreatedTime)
SELECT CustId, ResetDate, CreatedTime
FROM (  SELECT CustId, ResetDate, CreatedTime, ROW_NUMBER() OVER(PARTITION BY CustId ORDER BY ID DESC) AS RowNum
        FROM dbo.CustomerClassification_ResetBalance_History AS h with(nolock) 
		WHERE NOT EXISTS (SELECT 1 FROM #temp_ExcludedCustomers tmp WHERE tmp.CustID = h.CustId)
	) AS b 
WHERE b.RowNum = 1;

-- #2. Insert missing ResetBalance
INSERT INTO dbo.CustomerClassification_ResetBalance (CustId, ResetDate, CreatedTime)
OUTPUT INSERTED.CustId, INSERTED.ResetDate, INSERTED.CreatedTime,  GETDATE() INTO dbo.ResetBlance_RecoveryData_18032025(CustId, ResetDate, CreatedTime, InsertTime)
SELECT tmp.CustId, tmp.ResetDate, tmp.CreatedTime
FROM #tmpResetBlance AS tmp
WHERE NOT EXISTS (SELECT 1 FROM dbo.CustomerClassification_ResetBalance AS r with(nolock) WHERE r.CustId = tmp.CustId);


DROP TABLE #tmpResetBlance;

